import React, { useState } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Navbar from './components/Navbar';
import HomePage from './pages/HomePage';
import ProductListPage from './pages/ProductListPage';
import ProductDetailPage from './pages/ProductDetailPage';
import CartPage from './pages/CartPage';
import CheckoutPage from './pages/CheckoutPage';
import LoginPage from './pages/LoginPage';

function App() {
    const [user, setUser] = useState(null); // State to manage user login
    const [cart, setCart] = useState([]); // State to manage the cart

    // Handle successful login
    const handleLogin = (userData) => {
        setUser(userData); // Set user data
    };

    // Handle logout
    const handleLogout = () => {
        setUser(null); // Clear user data
        localStorage.removeItem('token'); // Remove token from storage
    };

    // Add item to cart
    const handleAddToCart = (product) => {
        setCart((prevCart) => {
            const existingProduct = prevCart.find((item) => item.id === product.id);
            if (existingProduct) {
                return prevCart.map((item) =>
                    item.id === product.id
                        ? { ...item, quantity: item.quantity + 1 }
                        : item
                );
            }
            return [...prevCart, { ...product, quantity: 1 }];
        });
    };

    // Remove item from cart
    const handleRemoveFromCart = (productId) => {
        setCart((prevCart) => prevCart.filter((item) => item.id !== productId));
    };

    // Update item quantity in the cart
    const handleUpdateQuantity = (productId, quantity) => {
        setCart((prevCart) =>
            prevCart.map((item) =>
                item.id === productId ? { ...item, quantity } : item
            )
        );
    };

    // Clear cart after checkout
    const handleClearCart = () => {
        setCart([]);
    };

    return (
        <Router>
            <Navbar user={user} cart={cart} onLogout={handleLogout} />
            <Routes>
                <Route path="/" element={<HomePage />} />
                <Route
                    path="/products"
                    element={<ProductListPage onAddToCart={handleAddToCart} />}
                />
                <Route path="/login" element={<LoginPage onLogin={handleLogin} />} />
                <Route path="/products/:id" element={<ProductDetailPage />} />
                <Route
                    path="/cart"
                    element={
                        <CartPage
                            cart={cart}
                            onRemoveFromCart={handleRemoveFromCart}
                            onUpdateQuantity={handleUpdateQuantity}
                        />
                    }
                />
                <Route
                    path="/checkout"
                    element={<CheckoutPage cart={cart} onClearCart={handleClearCart} />}
                />
            </Routes>
        </Router>
    );
}

export default App;
